package com.bank.record.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;

// ONE LINE replaces ~50 lines of POJO!
public record TradeConfirmation(
    String tradeId,
    String symbol,
    BigDecimal amount,
    String status,
    LocalDateTime timestamp
) {
    // COMPACT CONSTRUCTOR: validation
    public TradeConfirmation {
        if (tradeId == null || tradeId.isBlank()) throw new IllegalArgumentException("tradeId required");
        if (amount.signum() <= 0) throw new IllegalArgumentException("amount must be positive");
    }

    // Custom method:
    public boolean isSettled() { return "SETTLED".equals(status); }

    // Static factory:
    public static TradeConfirmation settled(String id, String symbol, BigDecimal amount) {
        return new TradeConfirmation(id, symbol, amount, "SETTLED", LocalDateTime.now());
    }
}
