// Regular class — NOT a record. JPA entity needs mutability.
package com.bank.record.model;

import java.math.BigDecimal;

public class Account {
    private String accountId;
    private BigDecimal balance;

    // JPA requires no-arg constructor:
    public Account() {}

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId;
        this.balance = balance;
    }

    // JPA needs setters for dirty checking:
    public void setBalance(BigDecimal balance) { this.balance = balance; }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }

    // Record CANNOT be used here:
    // 1. No no-arg constructor
    // 2. No setters (immutable)
    // 3. Final class (no proxying)
}
