```java
// ─── File: src/test/java/com/bank/record/RecordOopTest.java ───
package com.bank.record;

import com.bank.record.dto.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class RecordOopTest {

    // ═══ ENCAPSULATION: immutable, no setters ═══
    @Test
    void encapsulation_immutableFields() {
        TradeConfirmation tc = new TradeConfirmation("TRD-001", "RELIANCE",
            new BigDecimal("245050"), "SETTLED", LocalDateTime.now());
        // tc.tradeId = "HACKED";  → COMPILE ERROR! private final field.
        // No setTradeId() method. Immutable. True encapsulation.
        assertThat(tc.tradeId()).isEqualTo("TRD-001");
    }

    // ═══ VALUE SEMANTICS: equals based on ALL components ═══
    @Test
    void valueSemantic_equalsOnAllComponents() {
        LocalDateTime now = LocalDateTime.of(2024, 1, 15, 10, 30);
        TradeConfirmation t1 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t2 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t3 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("999999"), "SETTLED", now);

        assertThat(t1).isEqualTo(t2);      // same data → equal!
        assertThat(t1).isNotEqualTo(t3);    // different amount → NOT equal!
        // Auto-generated equals includes ALL components. No missing field bugs!
    }

    // ═══ HASHCODE: works correctly in HashSet ═══
    @Test
    void hashCode_worksInCollections() {
        LocalDateTime now = LocalDateTime.of(2024, 1, 15, 10, 30);
        TradeConfirmation t1 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);
        TradeConfirmation t2 = new TradeConfirmation("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED", now);

        Set<TradeConfirmation> set = new HashSet<>();
        set.add(t1);
        set.add(t2);  // duplicate — same data
        assertThat(set).hasSize(1);  // correctly deduplicated!
    }

    // ═══ TOSTRING: auto-generated, shows all fields ═══
    @Test
    void toString_showsAllComponents() {
        TradeConfirmation tc = TradeConfirmation.settled("TRD-001", "RELIANCE", new BigDecimal("245050"));
        String str = tc.toString();
        assertThat(str).contains("TRD-001").contains("RELIANCE").contains("245050").contains("SETTLED");
    }

    // ═══ COMPACT CONSTRUCTOR: validates ═══
    @Test
    void compactConstructor_validates() {
        assertThatThrownBy(() -> new TradeConfirmation(null, "X", BigDecimal.ONE, "OK", LocalDateTime.now()))
            .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("tradeId");

        assertThatThrownBy(() -> new TradeConfirmation("T1", "X", new BigDecimal("-1"), "OK", LocalDateTime.now()))
            .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("positive");
    }

    // ═══ RECORDS ARE FINAL — cannot extend ═══
    @Test
    void recordIsFinal() {
        // class SpecialTrade extends TradeConfirmation { }  → COMPILE ERROR!
        // Records are implicitly final. No inheritance hierarchy.
        assertThat(TradeConfirmation.class.getModifiers() & java.lang.reflect.Modifier.FINAL)
            .isNotZero();
    }

    // ═══ ACCESSORS: name() not getName() ═══
    @Test
    void accessors_componentNames() {
        AccountSummary as = new AccountSummary("SAV001", "Rajesh", new BigDecimal("125000"), "SAVINGS");
        assertThat(as.accountId()).isEqualTo("SAV001");    // accountId() not getAccountId()!
        assertThat(as.holderName()).isEqualTo("Rajesh");   // holderName() not getHolderName()!
    }

    // ═══ RECORDS PERFECT AS MAP KEYS ═══
    @Test
    void recordAsMapKey() {
        record CompositeKey(String accountId, String date) {}

        Map<CompositeKey, BigDecimal> balances = new HashMap<>();
        balances.put(new CompositeKey("SAV001", "2024-01-15"), new BigDecimal("125000"));

        // Lookup with DIFFERENT object but SAME data — works because equals/hashCode!
        BigDecimal found = balances.get(new CompositeKey("SAV001", "2024-01-15"));
        assertThat(found).isEqualByComparingTo("125000");  // found! equals/hashCode correct!
    }

    // ═══ RECORD vs POJO — the bug that records prevent ═══
    @Test
    void recordPreventsMissingFieldInEquals() {
        // POJO: developer forgot 'amount' in equals() → two trades with different amounts treated as equal!
        // Record: equals() auto-includes ALL components → bug impossible!

        LocalDateTime now = LocalDateTime.now();
        TradeConfirmation small = new TradeConfirmation("T1", "RELIANCE", new BigDecimal("100"), "OK", now);
        TradeConfirmation large = new TradeConfirmation("T1", "RELIANCE", new BigDecimal("99999"), "OK", now);
        assertThat(small).isNotEqualTo(large);  // different amount → NOT equal! (Recommended) 
        // With a buggy POJO that forgot amount in equals(): they would be EQUAL! Rs.2 crore bug!
    }
}
```

